<?php
session_start(); require __DIR__.'/config/db.php';
function h($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
function go($msg){$_SESSION['flash']=$msg;header('Location: index.php');exit;}
function auth(){if(empty($_SESSION['uid']))go('Please log in first.');return (int)$_SESSION['uid'];}
function staff(){auth();if($_SESSION['role']!=='staff')go('Staff only.');}
function query($sql,$params=[]){global $pdo;$s=$pdo->prepare($sql);$s->execute($params);return $s;}
if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($_SESSION['csrf'],$_POST['csrf']??''))exit('Invalid request token');
 $a=$_POST['action']??'';
 try {
 if($a==='signup'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$pw=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<8)throw new Exception('Enter name, valid email and password of at least 8 characters.');query('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)',[$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);go('Account created. Log in.');}
 if($a==='login'){$u=query('SELECT * FROM users WHERE email=?',[trim($_POST['email']??'')])->fetch();if(!$u||!password_verify($_POST['password']??'',$u['password_hash']))throw new Exception('Invalid login.');session_regenerate_id(true);$_SESSION['uid']=$u['id'];$_SESSION['role']=$u['role'];$_SESSION['name']=$u['name'];go('Welcome back!');}
 if($a==='logout'){$_SESSION=[];session_destroy();header('Location: index.php');exit;}
 $uid=auth();
 if($a==='register'){$sid=(int)$_POST['session_id'];$pdo->beginTransaction();$s=query('SELECT capacity FROM gym_sessions WHERE id=? FOR UPDATE',[$sid])->fetch();if(!$s)throw new Exception('Session not found.');$count=query("SELECT COUNT(*) FROM registrations WHERE session_id=? AND status='registered'",[$sid])->fetchColumn();if($count >= $s['capacity'])throw new Exception('Session is full.');query("INSERT INTO registrations(user_id,session_id,status) VALUES(?,?,'registered') ON DUPLICATE KEY UPDATE status='registered'",[$uid,$sid]);$pdo->commit();go('You are registered!');}
 if($a==='team'){$name=trim($_POST['team_name']??'');if(!$name)throw new Exception('Enter a team name.');$pdo->beginTransaction();query('INSERT INTO teams(name,captain_id,description) VALUES(?,?,?)',[$name,$uid,trim($_POST['description']??'')]);$tid=$pdo->lastInsertId();query('INSERT INTO team_memberships(team_id,user_id) VALUES(?,?)',[$tid,$uid]);$pdo->commit();go('Team created!');}
 if($a==='join'){$tid=(int)$_POST['team_id'];$t=query('SELECT * FROM teams WHERE id=?',[$tid])->fetch();if(!$t||!$t['recruiting'])throw new Exception('Team is not recruiting.');if(query('SELECT 1 FROM team_memberships WHERE team_id=? AND user_id=?',[$tid,$uid])->fetch())throw new Exception('Already a member.');query("INSERT INTO team_requests(team_id,user_id,status) VALUES(?,?,'pending') ON DUPLICATE KEY UPDATE status='pending'",[$tid,$uid]);go('Join request sent!');}
 if($a==='decide'){$rid=(int)$_POST['request_id'];$choice=$_POST['choice']==='approved'?'approved':'declined';$pdo->beginTransaction();$r=query('SELECT r.*,t.captain_id,t.max_players FROM team_requests r JOIN teams t ON t.id=r.team_id WHERE r.id=? FOR UPDATE',[$rid])->fetch();if(!$r||$r['captain_id']!=$uid||$r['status']!=='pending')throw new Exception('Cannot review this request.');if($choice==='approved'){$count=query('SELECT COUNT(*) FROM team_memberships WHERE team_id=?',[$r['team_id']])->fetchColumn();if($count >= $r['max_players'])throw new Exception('Team is full.');query('INSERT IGNORE INTO team_memberships(team_id,user_id) VALUES(?,?)',[$r['team_id'],$r['user_id']]);}query('UPDATE team_requests SET status=? WHERE id=?',[$choice,$rid]);$pdo->commit();go('Request updated.');}
 if($a==='request_equipment'){$eid=(int)$_POST['equipment_id'];if(!query('SELECT 1 FROM equipment WHERE id=?',[$eid])->fetch())throw new Exception('Equipment not found.');query("INSERT INTO equipment_checkouts(equipment_id,user_id) VALUES(?,?)",[$eid,$uid]);go('Equipment requested!');}
 if($a==='session'){staff();$title=trim($_POST['title']??'');$date=$_POST['starts_at']??'';$capacity=(int)($_POST['capacity']??0);if(!$title||!strtotime($date)||$capacity<1)throw new Exception('Enter valid session details.');query('INSERT INTO gym_sessions(title,starts_at,capacity,created_by) VALUES(?,?,?,?)',[$title,str_replace('T',' ',$date),$capacity,$uid]);go('Session created!');}
 if($a==='equipment'){staff();$name=trim($_POST['equipment_name']??'');$qty=(int)($_POST['quantity']??0);if(!$name||$qty<1)throw new Exception('Enter equipment and quantity.');query('INSERT INTO equipment(name,total_quantity,available_quantity) VALUES(?,?,?)',[$name,$qty,$qty]);go('Equipment added!');}
 if($a==='checkout'){staff();$id=(int)$_POST['checkout_id'];$mode=$_POST['mode']??'';$pdo->beginTransaction();$r=query('SELECT * FROM equipment_checkouts WHERE id=? FOR UPDATE',[$id])->fetch();if(!$r)throw new Exception('Checkout not found.');if($mode==='issue'&&$r['status']==='requested'){$e=query('SELECT * FROM equipment WHERE id=? FOR UPDATE',[$r['equipment_id']])->fetch();if($e['available_quantity']<$r['quantity'])throw new Exception('Not enough inventory.');query('UPDATE equipment SET available_quantity=available_quantity-? WHERE id=?',[$r['quantity'],$r['equipment_id']]);query("UPDATE equipment_checkouts SET status='checked_out',staff_id=? WHERE id=?",[$uid,$id]);}elseif($mode==='return'&&$r['status']==='checked_out'){query('UPDATE equipment SET available_quantity=available_quantity+? WHERE id=?',[$r['quantity'],$r['equipment_id']]);query("UPDATE equipment_checkouts SET status='returned' WHERE id=?",[$id]);}elseif($mode==='cancel'&&$r['status']==='requested'){query("UPDATE equipment_checkouts SET status='cancelled' WHERE id=?",[$id]);}else throw new Exception('Invalid checkout transition.');$pdo->commit();go('Equipment updated!');}
 throw new Exception('Unknown action.');
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['flash']='Error: '.$e->getMessage();header('Location: index.php');exit;}
}
$logged=!empty($_SESSION['uid']);$isStaff=$logged&&$_SESSION['role']==='staff';
$sessions=query("SELECT s.*, (SELECT COUNT(*) FROM registrations r WHERE r.session_id=s.id AND r.status='registered') AS enrolled FROM gym_sessions s ORDER BY starts_at")->fetchAll();
$teams=query('SELECT t.*,u.name AS captain,(SELECT COUNT(*) FROM team_memberships m WHERE m.team_id=t.id) AS members FROM teams t JOIN users u ON u.id=t.captain_id ORDER BY t.id DESC')->fetchAll();
$equipment=query('SELECT * FROM equipment ORDER BY name')->fetchAll();
$requests=$logged?query('SELECT r.*,t.name AS team_name,u.name AS requester FROM team_requests r JOIN teams t ON t.id=r.team_id JOIN users u ON u.id=r.user_id WHERE t.captain_id=? AND r.status="pending"',[$_SESSION['uid']])->fetchAll():[];
$checkouts=$isStaff?query('SELECT c.*,e.name AS equipment_name,u.name AS borrower FROM equipment_checkouts c JOIN equipment e ON e.id=c.equipment_id JOIN users u ON u.id=c.user_id ORDER BY c.id DESC')->fetchAll():[];
$myRegistrations=$logged?query("SELECT s.title,s.starts_at FROM registrations r JOIN gym_sessions s ON s.id=r.session_id WHERE r.user_id=? AND r.status='registered'",[$_SESSION['uid']])->fetchAll():[];
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hoop House</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f5f7fa}.navbar{background:#101f3b}.brand{color:#f7a21b}.card{border:0;box-shadow:0 3px 14px #15253b12}.section-title{border-left:4px solid #f7a21b;padding-left:12px}button{white-space:nowrap}</style></head><body>
<nav class="navbar navbar-dark mb-4"><div class="container"><a class="navbar-brand fw-bold" href="index.php">🏀 <span class="brand">HOOP HOUSE</span></a><div class="text-white"><?= $logged?'Hi, '.h($_SESSION['name']).' ('.h($_SESSION['role']).')':'Basketball Facility Management' ?></div><?php if($logged): ?><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><button class="btn btn-outline-light btn-sm" name="action" value="logout">Log out</button></form><?php endif; ?></div></nav>
<main class="container pb-5"><?php if(!empty($_SESSION['flash'])): ?><div class="alert alert-info"><?=h($_SESSION['flash'])?></div><?php unset($_SESSION['flash']);endif;?>
<?php if(!$logged): ?><div class="row g-4"><div class="col-md-6"><div class="card p-4"><h3>Log in</h3><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input class="form-control mb-2" name="email" type="email" placeholder="Email" required><input class="form-control mb-3" name="password" type="password" placeholder="Password" required><button class="btn btn-primary" name="action" value="login">Log in</button></form></div></div><div class="col-md-6"><div class="card p-4"><h3>Create account</h3><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input class="form-control mb-2" name="name" placeholder="Full name" required><input class="form-control mb-2" name="email" type="email" placeholder="Email" required><input class="form-control mb-3" name="password" type="password" minlength="8" placeholder="Password (8+ characters)" required><button class="btn btn-warning" name="action" value="signup">Sign up</button></form></div></div></div><?php else: ?>
<h1 class="mb-1"><?= $isStaff?'Staff Dashboard':'Customer Dashboard' ?></h1><p class="text-muted mb-4">Find your game. Build your team. Get on the court.</p>
<?php if($isStaff): ?><section class="card p-4 mb-4"><h4 class="section-title">Create gym session</h4><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><div class="col-md-4"><input class="form-control" name="title" placeholder="Session title" required></div><div class="col-md-4"><input class="form-control" name="starts_at" type="datetime-local" required></div><div class="col-md-2"><input class="form-control" name="capacity" type="number" min="1" placeholder="Capacity" required></div><div class="col-md-2"><button class="btn btn-primary w-100" name="action" value="session">Create</button></div></form></section><?php endif; ?>
<section class="mb-4"><h3 class="section-title">Open Gym</h3><div class="row g-3"><?php foreach($sessions as $s): ?><div class="col-md-4"><div class="card p-3 h-100"><h5><?=h($s['title'])?></h5><p><?=h($s['starts_at'])?><br><?=h($s['enrolled'])?> / <?=h($s['capacity'])?> spots filled</p><?php if(!$isStaff): ?><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="session_id" value="<?=h($s['id'])?>"><button class="btn btn-primary" name="action" value="register" <?= $s['enrolled'] >= $s['capacity']?'disabled':'' ?>>Register</button></form><?php endif; ?></div></div><?php endforeach; ?><?php if(!$sessions): ?><p>No gym sessions yet. Staff can create one.</p><?php endif; ?></div></section>
<?php if(!$isStaff): ?><section class="card p-4 mb-4"><h4 class="section-title">My Gym Registrations</h4><?php foreach($myRegistrations as $r): ?><p class="mb-1">✓ <?=h($r['title'])?> — <?=h($r['starts_at'])?></p><?php endforeach; ?><?php if(!$myRegistrations): ?><p>No registrations yet.</p><?php endif; ?></section><section class="card p-4 mb-4"><h4 class="section-title">Create a Team</h4><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><div class="col-md-4"><input class="form-control" name="team_name" placeholder="Team name" required></div><div class="col-md-6"><input class="form-control" name="description" placeholder="About your team"></div><div class="col-md-2"><button class="btn btn-warning w-100" name="action" value="team">Create</button></div></form></section><?php endif; ?>
<section class="mb-4"><h3 class="section-title">Find a Team</h3><div class="row g-3"><?php foreach($teams as $t): ?><div class="col-md-4"><div class="card p-3 h-100"><h5><?=h($t['name'])?></h5><p class="mb-1"><?=h($t['description'])?></p><p class="text-muted">Captain: <?=h($t['captain'])?><br><?=h($t['members'])?> / <?=h($t['max_players'])?> players</p><?php if(!$isStaff && $t['recruiting'] && $t['members']<$t['max_players'] && $t['captain_id']!=$_SESSION['uid']): ?><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="team_id" value="<?=h($t['id'])?>"><button class="btn btn-outline-primary" name="action" value="join">Request to Join</button></form><?php endif; ?></div></div><?php endforeach; ?><?php if(!$teams): ?><p>No teams yet. Create the first one!</p><?php endif; ?></div></section>
<?php if($requests): ?><section class="card p-4 mb-4"><h4 class="section-title">Team Join Requests</h4><?php foreach($requests as $r): ?><div class="d-flex gap-2 align-items-center mb-2"><span><?=h($r['requester'])?> wants to join <?=h($r['team_name'])?></span><?php foreach(['approved'=>'Approve','declined'=>'Decline'] as $v=>$label): ?><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="request_id" value="<?=h($r['id'])?>"><input type="hidden" name="choice" value="<?=h($v)?>"><button class="btn btn-sm btn-outline-secondary" name="action" value="decide"><?=h($label)?></button></form><?php endforeach; ?></div><?php endforeach; ?></section><?php endif; ?>
<section class="mb-4"><h3 class="section-title">Free Equipment Checkout</h3><div class="row g-3"><?php foreach($equipment as $e): ?><div class="col-md-4"><div class="card p-3 h-100"><h5><?=h($e['name'])?></h5><p><?=h($e['available_quantity'])?> available • Free</p><?php if(!$isStaff): ?><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="equipment_id" value="<?=h($e['id'])?>"><button class="btn btn-outline-primary" name="action" value="request_equipment">Request Checkout</button></form><?php endif; ?></div></div><?php endforeach; ?></div></section>
<?php if($isStaff): ?><section class="card p-4 mb-4"><h4 class="section-title">Add Equipment</h4><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><div class="col-md-5"><input class="form-control" name="equipment_name" placeholder="Equipment name" required></div><div class="col-md-3"><input class="form-control" type="number" name="quantity" min="1" placeholder="Quantity" required></div><div class="col-md-4"><button class="btn btn-primary" name="action" value="equipment">Add Equipment</button></div></form></section><section class="card p-4"><h4 class="section-title">Equipment Requests & Returns</h4><?php foreach($checkouts as $c): ?><div class="border-bottom py-2 d-flex flex-wrap gap-2 align-items-center"><span><?=h($c['borrower'])?> — <?=h($c['equipment_name'])?> (<?=h($c['status'])?>)</span><?php $actions=$c['status']==='requested'?['issue'=>'Issue','cancel'=>'Cancel']:($c['status']==='checked_out'?['return'=>'Mark Returned']:[]);foreach($actions as $v=>$label): ?><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="checkout_id" value="<?=h($c['id'])?>"><input type="hidden" name="mode" value="<?=h($v)?>"><button class="btn btn-sm btn-outline-primary" name="action" value="checkout"><?=h($label)?></button></form><?php endforeach; ?></div><?php endforeach; ?></section><?php endif; ?>
<?php endif; ?></main></body></html>
